import{_ as a,o as t,c as o,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const m=JSON.parse('{"title":"FR 3.5.7 — Update Media Campaign","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/04-media-package-campaign/3-5-7-update-media-campaign/spec.md","filePath":"feature/srs/04-media-package-campaign/3-5-7-update-media-campaign/spec.md"}'),i={name:"feature/srs/04-media-package-campaign/3-5-7-update-media-campaign/spec.md"};function c(s,e,r,d,l,g){return t(),o("div",null,[...e[0]||(e[0]=[n('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-5-7-—-update-media-campaign" tabindex="-1">FR 3.5.7 — Update Media Campaign <a class="header-anchor" href="#fr-3-5-7-—-update-media-campaign" aria-label="Permalink to &quot;FR 3.5.7 — Update Media Campaign&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.5.7</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-046</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Update Media Campaign</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Media Package &amp; Media Campaign (<code>FR 3.5</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-27</code></td></tr><tr><td style="text-align:left;"><strong>Document Status</strong></td><td style="text-align:left;">Implemented &amp; Verified</td></tr></tbody></table><h2 id="_1-objective-business-context" tabindex="-1">1. Objective &amp; Business Context <a class="header-anchor" href="#_1-objective-business-context" aria-label="Permalink to &quot;1. Objective &amp; Business Context&quot;">​</a></h2><p>Cập nhật nội dung Kế hoạch Chiến dịch Truyền thông và gửi phản hồi điều chỉnh trước khi phê duyệt chính thức (Update Media Campaign — /workspaces/:id/campaigns/:campaignId). Cho phép Agency chỉnh sửa danh sách hạng mục bài viết, mốc thời gian, kênh phân phối theo góp ý của Client khi chiến dịch đang ở trạng thái DRAFT hoặc PENDING_APPROVAL (BR-27).</p><p><strong>Architectural &amp; Workflow Alignment:</strong> Enforces optimistic concurrency (<code>expectedVersion</code> -&gt; <code>content_version + 1</code> with <code>CampaignVersion</code> snapshot on <code>Owner</code>/<code>Manager</code> plan &amp; brief edits, <code>BR-27</code>), allows <code>Client</code> to submit structured review feedback (<code>POST /feedback</code> -&gt; <code>CampaignReviewEvent</code>) without mutating package terms, and supports timeline task scheduling plus third-party partner status updates (<code>CONTACTED</code>, <code>NEGOTIATING</code>, <code>CONFIRMED</code>, <code>LIVE</code>).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized actor (<code>Owner, Manager, Client</code>), I want to execute <strong>Update Media Campaign</strong> with deterministic state validation, version-safe concurrency control, and strict Workspace/Agency isolation, so that commercial deliverables, Campaign schedules, and supplemental requests stay 100% synchronized (<code>BR-27</code>).</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Role &amp; Scope Enforcement:</strong> Only authenticated users holding <code>Owner, Manager, Client</code> in the target Agency/Workspace (plus <code>Guest</code> solely on public share token view <code>/api/v1/public/media-packages/{token}</code> in <code>3.5.2</code>) may invoke <code>PATCH /api/v1/workspaces/{workspaceId}/campaigns/{campaignId} · PATCH /brief · POST /feedback · PATCH /tasks/{taskId}/schedule · POST|PUT|DELETE /campaigns/{campaignId}/collaborators</code>; unauthorized requests receive <code>401</code> / <code>403</code>.</li><li><strong>Domain &amp; State Machine Invariants (<code>BR-27</code>):</strong> <code>MediaCampaignService, CampaignTimelineService, CampaignCollaboratorService</code> enforces state transition guards, version matching (<code>expectedTermsVersion</code> / <code>expectedVersion</code>), date boundaries in canonical Workspace timezone (<code>Asia/Ho_Chi_Minh</code> default), and snapshot isolation between Agency templates, Workspace packages, Campaigns, and Tasks.</li><li><strong>Hybrid Persistence Consistency:</strong> State changes across PostgreSQL <code>media_campaigns</code> (<code>content_version</code>), <code>campaign_versions</code>, <code>campaign_review_events</code>, <code>campaign_collaborators</code>; MongoDB <code>tasks</code> return standardized <code>ApiResponse&lt;T&gt;</code> envelopes with explicit <code>ErrorCode</code> mappings (<code>400 VALIDATION_ERROR</code>, <code>403 FORBIDDEN</code>, <code>404 CAMPAIGN_NOT_FOUND</code>, <code>409 CAMPAIGN_VERSION_CONFLICT</code> / <code>CAMPAIGN_LOCKED</code>), leaving zero duplicate Campaigns or duplicate Tasks on retry.</li><li><strong>Internationalization (<code>vi</code> / <code>en</code>):</strong> All labels, status badges, impact confirmation dialogs, empty states, and error messages use key-parallel entries (<code>campaign.edit.* / campaign.brief.* / campaign.feedback.*</code>) in <code>src/i18n/locales/vi/*.json</code> and <code>en/*.json</code> — zero hardcoded strings.</li><li><strong>Semantic Light/Dark Theme &amp; Responsive UX:</strong> Web (<code>src/pages/campaign/{index,page}.tsx</code>, <code>src/pages/campaign/components/{CampaignBriefChipGroup,CampaignBriefFormatSections}.tsx</code>) and Mobile (<code>src/screens/more/CampaignDetailScreen.tsx</code>, <code>src/services/campaignService.ts</code>) surfaces use semantic theme tokens (<code>dark:</code> variants / <code>useTheme()</code>) with full keyboard navigation and mobile usability.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surface (<code>brandhub-web</code>):</strong> <code>src/pages/campaign/{index,page}.tsx</code>, <code>src/pages/campaign/components/{CampaignBriefChipGroup,CampaignBriefFormatSections}.tsx</code></li><li><strong>Mobile Surface (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/CampaignDetailScreen.tsx</code>, <code>src/services/campaignService.ts</code></li><li><strong>State Coverage:</strong><ul><li><strong>Loading / In-Flight:</strong> Skeleton placeholders and disabled action buttons while mutations execute.</li><li><strong>Empty / Unconfigured:</strong> Role-specific guidance (e.g., guiding <code>Manager</code> to configure package/campaign or informing <code>Client</code> that preparation is underway) — never substituting synthetic mock data.</li><li><strong>Conflict (<code>409</code>):</strong> Preserves unsaved user input/notes in the form/modal and prompts a clean reload of the latest version before re-submitting.</li><li><strong>Success:</strong> Immediate TanStack Query invalidation across package, campaign, task, and request caches with localized toast feedback.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><ul><li><strong>Endpoints:</strong> <code>PATCH /api/v1/workspaces/{workspaceId}/campaigns/{campaignId} · PATCH /brief · POST /feedback · PATCH /tasks/{taskId}/schedule · POST|PUT|DELETE /campaigns/{campaignId}/collaborators</code></li><li><strong>Controllers (<code>brandhub-business-service</code>):</strong> <code>WorkspaceCampaignController.update() / updateBrief() / feedback(), CampaignTimelineController.schedule() / createOutOfScopeTask() / reorderTasks(), CampaignCollaboratorController.assign() / update() / unlink()</code></li><li><strong>Services:</strong> <code>MediaCampaignService, CampaignTimelineService, CampaignCollaboratorService</code></li><li><strong>Repositories / Stores:</strong> MediaCampaignRepository, CampaignVersionRepository, CampaignReviewEventRepository, CampaignCollaboratorRepository</li></ul><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Deterministic Domain Errors:</strong> <code>400 VALIDATION_ERROR</code>, <code>403 FORBIDDEN</code>, <code>404 CAMPAIGN_NOT_FOUND</code>, <code>409 CAMPAIGN_VERSION_CONFLICT</code> / <code>CAMPAIGN_LOCKED</code>.</li><li><strong>Retry &amp; Concurrency Safety:</strong> Pessimistic row locks (<code>PESSIMISTIC_WRITE</code> on <code>workspace_media_packages</code> agreement lock) and optimistic version predicates (<code>terms_version</code>, <code>content_version</code>, MongoDB <code>version</code>) prevent lost updates or duplicate task generation when <code>Manager</code> and <code>Client</code> act simultaneously.</li><li><strong>Historical Audit Preservation:</strong> Negotiation events (<code>package_negotiation_events</code>), campaign versions (<code>campaign_versions</code>), review feedback (<code>campaign_review_events</code>), and cancelled/denied requests remain immutable in history views.</li></ul><h2 id="_7-definition-of-done-cross-references" tabindex="-1">7. Definition of Done &amp; Cross-References <a class="header-anchor" href="#_7-definition-of-done-cross-references" aria-label="Permalink to &quot;7. Definition of Done &amp; Cross-References&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Backend controller/service logic verified by unit &amp; integration tests (<a href="./test.html">test.md</a>), Web and Mobile UI connected to live endpoints, <code>vi</code>/<code>en</code> locale parity verified, and Light/Dark themes verified.</li><li><strong>Out of Scope:</strong> Adjacent lifecycle transitions handled by sibling FRs in <code>3.5.1–3.5.13</code> and Task execution/approval workflows in <code>3.6.1–3.6.10</code>.</li><li><strong>Related Documentation:</strong> <a href="./../../../../ba/04-media-package-campaign.html">BA Media Package &amp; Campaign Spec</a> · <a href="./../../../../ba/12-state-machines.html">State Machines</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul>',18)])])}const h=a(i,[["render",c]]);export{m as __pageData,h as default};
